  'This course develops professional nursing leadership across scope and identity, leadership theory, healthcare systems, unit operations, delegation, staffing, teamwork, conflict, quality improvement, patient safety, finance, policy, change, equity, and the transition to practice.',
  $nlmjson${"slug": "nursing-leadership-and-management", "title": "Nursing Leadership and Management", "description": "This course develops professional nursing leadership across scope and identity, leadership theory, healthcare systems, unit operations, delegation, staffing, teamwork, conflict, quality improvement, patient safety, finance, policy, change, equity, and the transition to practice.", "topics": [{"id": "106922e5-449b-4870-bb7d-3c37566669b9", "type": "topic", "title": "Professional Nursing Leadership, Identity, and Scope", "description": "Frame leadership as a professional nursing responsibility grounded in scope, standards, ethics, accountability, and patient-centered systems practice.", "children": [{"id": "419501e6-802a-4192-a4c7-9500549dc4ad", "type": "subtopic", "title": "Professional identity and leadership role formation", "description": "This subtopic helps students see leadership as part of everyday nursing practice, not only as a formal manager title.", "children": [{"id": "590d59d1-5b35-446b-bfb5-bd93ba101a2e", "type": "concept", "title": "Professional values"}, {"id": "cd20ae59-9ba9-4400-bd39-818607360019", "type": "concept", "title": "Accountability"}, {"id": "376ab1f4-0895-4271-a1aa-83e9d1c1273a", "type": "concept", "title": "Role modeling"}, {"id": "13107723-8e4f-4a4c-8adc-d56a1c258492", "type": "concept", "title": "Clinical judgment and influence"}]}, {"id": "cce49d6d-7f5f-45a8-bcca-d6df607fda2a", "type": "subtopic", "title": "Scope, standards, and ethics", "description": "Scope and standards define the boundaries and expectations that make nursing leadership safe, legitimate, and patient-centered.", "children": [{"id": "2c008442-a5ed-4720-b85a-1c8fe05fec72", "type": "concept", "title": "ANA scope and standards"}, {"id": "a82a1b26-c1a4-41f1-811f-7155abf8aa7d", "type": "concept", "title": "Code of ethics"}, {"id": "babfcee2-e178-4f3e-a993-f1806ac45c4b", "type": "concept", "title": "Standards of care"}, {"id": "4e64cb60-ab6e-4bf8-a793-0f2f6507b8c1", "type": "concept", "title": "Professional boundaries"}]}, {"id": "4fcba7e3-0ea9-4326-9f1b-4595c1821838", "type": "subtopic", "title": "Leadership at the point of care", "description": "Point-of-care leadership shows how nurses shape outcomes through coordination, escalation, advocacy, and team sensemaking.", "children": [{"id": "b69c1c86-be6a-447c-9506-d28845de985e", "type": "concept", "title": "Patient advocacy"}, {"id": "4f16f2aa-60fc-4af1-a8a9-e4a1925effca", "type": "concept", "title": "Escalation of concerns"}, {"id": "ed7c8122-d25c-4b5b-b101-227386d2be1e", "type": "concept", "title": "Situational awareness"}, {"id": "edb933db-7b51-4e57-90a9-41e321e2067a", "type": "concept", "title": "Shared decision-making"}]}]}, {"id": "9e325c48-35a2-45bc-b5f1-d6c857d2912e", "type": "topic", "title": "Leadership Theories and Styles in Nursing", "description": "Compare major leadership approaches and learn when different styles support safety, learning, coordination, and staff development.", "children": [{"id": "b39ce42b-6b16-472c-872a-8e6d5931d64e", "type": "subtopic", "title": "Classical and contemporary leadership theories", "description": "Leadership theories give students a vocabulary for diagnosing situations and choosing a productive approach.", "children": [{"id": "d95c836e-23fe-4134-bb25-2bb5214bebb4", "type": "concept", "title": "Trait and behavioral theories"}, {"id": "4197e4af-990b-49de-9c97-c85bf414fc68", "type": "concept", "title": "Situational leadership"}, {"id": "8ed8829c-9317-4525-9789-3ef8b65388d0", "type": "concept", "title": "Transformational leadership"}, {"id": "ed2000af-4b3f-45ea-aad9-c977edb717b9", "type": "concept", "title": "Servant leadership"}]}, {"id": "f0942531-1789-438f-b5a4-92bb726e0cb5", "type": "subtopic", "title": "Clinical leadership styles", "description": "Leadership style matters because different teams, risks, and patient situations require different levels of direction and participation.", "children": [{"id": "9ba279f7-ade3-4d00-8058-73e2245251f9", "type": "concept", "title": "Democratic leadership"}, {"id": "50fd8818-6198-485e-9d56-d41002b0aa11", "type": "concept", "title": "Autocratic leadership"}, {"id": "2cffc09c-8149-4b8b-b962-78bcc504f1d5", "type": "concept", "title": "Laissez-faire risks"}, {"id": "f14910e2-7392-4184-9d03-547d0748de77", "type": "concept", "title": "Coaching and mentoring"}]}, {"id": "8438bf36-96ca-4ba5-87e5-58e3005a5926", "type": "subtopic", "title": "Emotional intelligence and self-leadership", "description": "Self-awareness and emotional regulation help nurse leaders make better decisions under pressure and maintain trust.", "children": [{"id": "4a1f9d08-a895-46d4-a632-b94b2fe9473b", "type": "concept", "title": "Self-awareness"}, {"id": "b7b402eb-d087-420e-819c-8b53cb3e9a1b", "type": "concept", "title": "Empathy"}, {"id": "8e196c29-e477-44f1-971a-cf622a061366", "type": "concept", "title": "Resilience"}, {"id": "5fe46517-4486-4207-8bdb-311f122cab8f", "type": "concept", "title": "Reflective practice"}]}]}, {"id": "bb253a2f-9eed-4388-9cb9-c0c630100324", "type": "topic", "title": "Healthcare Delivery Systems and Systems Thinking", "description": "Understand how care is organized across units, organizations, payment models, regulations, and interprofessional networks.", "children": [{"id": "4927bb15-7053-486e-88c2-8269807921e3", "type": "subtopic", "title": "Healthcare delivery models", "description": "Students learn how hospitals, ambulatory care, public health, long-term care, and community settings organize work differently.", "children": [{"id": "3add993c-6ed4-41ca-8366-0311314433ef", "type": "concept", "title": "Acute care"}, {"id": "031a3f05-0146-469d-8998-65d9d314d48d", "type": "concept", "title": "Primary and ambulatory care"}, {"id": "682077b4-4069-41fe-82ea-4a353f63f067", "type": "concept", "title": "Community health"}, {"id": "0ccfc3a5-a493-45ff-b39f-05cb42bb3ba6", "type": "concept", "title": "Continuum of care"}]}, {"id": "4fb4390c-afad-40b3-bc25-dc28f91f298c", "type": "subtopic", "title": "Systems thinking", "description": "Systems thinking shifts attention from isolated errors to patterns, structures, incentives, and feedback loops.", "children": [{"id": "8ab44318-f9f9-4a98-8d73-01faf2cb701a", "type": "concept", "title": "Microsystems and macrosystems"}, {"id": "6efad2fe-7c48-426e-9e26-4e0f9b6ce270", "type": "concept", "title": "Feedback loops"}, {"id": "9839fdd2-e828-4f0b-8611-8b75fd80693e", "type": "concept", "title": "Bottlenecks"}, {"id": "951b17a8-6745-4f60-8152-66298f93bbdd", "type": "concept", "title": "Unintended consequences"}]}, {"id": "7eea7c5b-a579-487c-9b14-7024c27563bb", "type": "subtopic", "title": "Payment, access, and care coordination", "description": "Leaders need to understand how financing and transitions shape patient experience, quality, and equity.", "children": [{"id": "b49a42bb-430c-4d14-97cd-3387f96cb9f3", "type": "concept", "title": "Value-based care"}, {"id": "244caaff-f4f5-4271-af88-b10171752abc", "type": "concept", "title": "Population health"}, {"id": "be22409e-9a9f-4d06-9936-96e3231ac746", "type": "concept", "title": "Care transitions"}, {"id": "d0dbfb0b-7cf3-4292-baf8-a844567fdde6", "type": "concept", "title": "Social drivers of health"}]}]}, {"id": "ff3d732e-b6ff-45d2-a966-37d8370faa2a", "type": "topic", "title": "Management Functions, Unit Operations, and Organizational Behavior", "description": "Build practical fluency in planning, organizing, directing, controlling, decision-making, and leading daily care operations.", "children": [{"id": "f776a664-1e19-4f38-bb62-69fd5b308116", "type": "subtopic", "title": "Core management functions", "description": "Management functions translate leadership intent into reliable daily operations.", "children": [{"id": "5d90e6e8-a012-482b-8cf5-e239acbc117a", "type": "concept", "title": "Planning"}, {"id": "f2fb4840-e4e2-4d70-ae1e-85c2df2568e3", "type": "concept", "title": "Organizing"}, {"id": "dfd53844-164f-4005-aa34-c39adc624770", "type": "concept", "title": "Staffing"}, {"id": "0f8c2236-a305-4ff7-8003-3295e31bcf75", "type": "concept", "title": "Directing and controlling"}]}, {"id": "91bf87ab-a313-4464-b641-d889572e2373", "type": "subtopic", "title": "Unit operations and workflow", "description": "Operational fluency helps students understand how assignments, admissions, discharges, supplies, and communication affect safety.", "children": [{"id": "822ca0c4-e6ad-480e-9766-476bfac83afb", "type": "concept", "title": "Patient flow"}, {"id": "32d4c3de-888d-45c2-b1bd-bfe9f32f1636", "type": "concept", "title": "Bed management"}, {"id": "f1b4326d-32bd-470d-9353-2ed2d4012d7f", "type": "concept", "title": "Supply chain basics"}, {"id": "4bf3a040-5ffa-4c29-ad49-55af2fdcacdd", "type": "concept", "title": "Workflow reliability"}]}, {"id": "747f9b72-ed06-40ee-b4a7-84591e2b0621", "type": "subtopic", "title": "Organizational behavior in health systems", "description": "Organizational behavior explains why culture, motivation, power, and informal norms influence care quality.", "children": [{"id": "dc819ae1-78c8-4429-8029-aac63a278738", "type": "concept", "title": "Motivation"}, {"id": "11ab1e32-0ca2-4ce6-952b-2aa249177473", "type": "concept", "title": "Power and influence"}, {"id": "9b477adf-facf-43a9-b465-e1fef3d4747f", "type": "concept", "title": "Organizational culture"}, {"id": "02cfa1ab-f003-402d-9b19-8aee436bde0d", "type": "concept", "title": "Decision-making structures"}]}]}, {"id": "96414701-24c5-48e3-963d-5a533d268ac0", "type": "topic", "title": "Delegation, Supervision, Assignment, and Accountability", "description": "Practice safe delegation and supervision by matching tasks, patient needs, staff competence, scope, and accountability.", "children": [{"id": "0e3aa89c-8d52-4f1a-a95b-35237e493a01", "type": "subtopic", "title": "Safe delegation frameworks", "description": "Delegation is learned as a safety-critical reasoning process rather than a shortcut for getting work done.", "children": [{"id": "9d8015ca-0743-4e91-8eab-d87068120e0a", "type": "concept", "title": "Right task"}, {"id": "aaa86426-aeb2-4b8d-b2a6-657e87cfe65f", "type": "concept", "title": "Right circumstance"}, {"id": "ac453132-f834-439e-be57-e92d1636b441", "type": "concept", "title": "Right person"}, {"id": "6a331db1-13e3-4bda-84e9-652ce600b5a4", "type": "concept", "title": "Right direction and supervision"}]}, {"id": "fdca1d83-2e57-48dc-a8e6-97c9605d6584", "type": "subtopic", "title": "Supervision and follow-up", "description": "Supervision closes the loop so delegated work remains safe, visible, and accountable.", "children": [{"id": "310a1d92-1746-4a30-853f-a9d7a8e14058", "type": "concept", "title": "Clear expectations"}, {"id": "f81a46c6-1edc-4d1e-8aba-c7d084a786ec", "type": "concept", "title": "Feedback loops"}, {"id": "4d6c9abc-f73f-4e78-9c97-f7f79f9d3212", "type": "concept", "title": "Competency verification"}, {"id": "8f779afc-9e9b-4ef9-8953-0d7c71515b68", "type": "concept", "title": "Escalation triggers"}]}, {"id": "6fc104fe-b705-4020-8efd-bd59070372ae", "type": "subtopic", "title": "Scope and legal accountability", "description": "Students connect delegation decisions to licensure, institutional policy, patient acuity, and professional responsibility.", "children": [{"id": "dfcb8f75-c9fb-4c56-947c-5163805d7718", "type": "concept", "title": "RN scope"}, {"id": "178f057d-a2ad-4311-8392-115fa1c03a74", "type": "concept", "title": "LPN/LVN scope"}, {"id": "7ec87abe-ff54-4196-bfb6-2ea38e878d02", "type": "concept", "title": "Unlicensed assistive personnel"}, {"id": "b9093f12-91df-42e9-a402-c3d1d80731c5", "type": "concept", "title": "Documentation"}]}]}, {"id": "025e4917-344d-4262-b6d7-124297dbbb2a", "type": "topic", "title": "Staffing, Scheduling, Workload, and Workforce Well-Being", "description": "Learn how nurse leaders balance patient acuity, staffing models, labor constraints, fatigue risk, retention, and healthy work environments.", "children": [{"id": "400963a7-d74c-4233-877c-5ed731d5c95f", "type": "subtopic", "title": "Staffing models and acuity", "description": "Staffing decisions should reflect patient need, nursing workload, skill mix, and safety risk.", "children": [{"id": "4edc788f-36bd-4a38-bacf-1677f5d5b27a", "type": "concept", "title": "Acuity systems"}, {"id": "1baf7aee-188b-4f2f-832a-0a9eda99e0ea", "type": "concept", "title": "Nurse-patient ratios"}, {"id": "247c3192-b558-440e-b3fa-49d2332c38ad", "type": "concept", "title": "Skill mix"}, {"id": "c328db59-7ac2-46c4-b954-35e24b352f08", "type": "concept", "title": "Float pools"}]}, {"id": "9528ee0b-30ac-4de6-9db8-0a9b3e364129", "type": "subtopic", "title": "Scheduling and fatigue risk", "description": "Scheduling is treated as a patient-safety and workforce-sustainability issue.", "children": [{"id": "23914f0e-200b-4c53-b184-7808a0a8c731", "type": "concept", "title": "Shift length"}, {"id": "f554ca15-8695-4bd0-9f41-84a18b8f391d", "type": "concept", "title": "Overtime"}, {"id": "7ace98f2-80ef-4bd4-8a6f-9dd166d54971", "type": "concept", "title": "Circadian disruption"}, {"id": "40ad810d-1ca0-42a3-a90e-60402a058abe", "type": "concept", "title": "Rest and recovery"}]}, {"id": "01371804-2003-4b34-b02c-dd45cc54890a", "type": "subtopic", "title": "Retention and healthy work environments", "description": "Nurse leaders influence whether staff feel supported, respected, and able to practice safely.", "children": [{"id": "a478314c-62e9-4b5f-b064-84c26d54715e", "type": "concept", "title": "Burnout prevention"}, {"id": "3f3c04b1-630a-4b43-90e9-54aa5d4076a8", "type": "concept", "title": "Moral distress"}, {"id": "bd171a6b-6280-474a-a0b1-44346e5b66fb", "type": "concept", "title": "Recognition"}, {"id": "e4ee2a82-bed0-4e66-afb2-b5fc798e2a02", "type": "concept", "title": "Shared governance"}]}]}, {"id": "a3a6c4f9-8dbf-41b8-b129-ca92abc665fc", "type": "topic", "title": "Teamwork, Interprofessional Collaboration, and TeamSTEPPS Communication", "description": "Use structured communication and team leadership tools to coordinate care, reduce errors, and improve team performance.", "children": [{"id": "1bd6e206-bb1a-4405-8bf2-2d42a92f432a", "type": "subtopic", "title": "Team roles and interprofessional collaboration", "description": "Students learn how nurses coordinate across disciplines while preserving patient goals and professional clarity.", "children": [{"id": "a8c80e08-2dae-46f4-ac26-111cc5963bde", "type": "concept", "title": "Role clarity"}, {"id": "313fa33f-aaa9-4e50-a480-1e74530c5c1e", "type": "concept", "title": "Consultation"}, {"id": "26d99fda-1cad-42d0-a205-4904a71fccad", "type": "concept", "title": "Care conferences"}, {"id": "b1cf9cc8-308a-4680-ae7d-e1af0e1451b5", "type": "concept", "title": "Collaborative practice"}]}, {"id": "cf8b5d1b-9252-42da-8849-ed791fad8225", "type": "subtopic", "title": "Structured communication tools", "description": "Structured tools reduce ambiguity during handoffs, escalation, and urgent clinical coordination.", "children": [{"id": "3df03351-0409-405a-a02c-c05c871ef574", "type": "concept", "title": "SBAR"}, {"id": "8f5412ad-d53b-4c12-8c16-5172589d387f", "type": "concept", "title": "Closed-loop communication"}, {"id": "1e61fbc4-af53-47b9-a9e3-00d069df5487", "type": "concept", "title": "Check-back"}, {"id": "d6884ab7-51de-4442-ad7a-e02640849455", "type": "concept", "title": "Handoffs"}]}, {"id": "e8a543a7-cb2a-401a-864e-769d0d5a8a9b", "type": "subtopic", "title": "Team leadership and performance", "description": "TeamSTEPPS-style leadership builds shared mental models and supports teams during routine and high-stress care.", "children": [{"id": "d79afe6e-b657-4a7b-8fef-8f93c9ef05c3", "type": "concept", "title": "Briefs"}, {"id": "775a2674-0311-4853-958b-d5ebb81b2111", "type": "concept", "title": "Huddles"}, {"id": "e4fa450e-07ac-43f1-bc1c-6952f2226618", "type": "concept", "title": "Debriefs"}, {"id": "c2610fdf-b8a6-4bc7-951e-99e046fd2209", "type": "concept", "title": "Mutual support"}]}]}, {"id": "ab485e5f-0e9a-4dfb-9cca-a2b2a88c9cee", "type": "topic", "title": "Conflict Management, Negotiation, and Psychological Safety", "description": "Develop methods for addressing disagreement, incivility, moral distress, and power dynamics while preserving safety and trust.", "children": [{"id": "fcc60702-7f65-4a1c-b196-4fd9b8fae33f", "type": "subtopic", "title": "Conflict diagnosis", "description": "Students learn to distinguish task conflict, relationship conflict, ethical conflict, and system-generated tension.", "children": [{"id": "b8b61d86-5eb9-4c82-8bac-49c26b615e72", "type": "concept", "title": "Sources of conflict"}, {"id": "77b567d0-5645-4545-bc18-4f5325d8deaa", "type": "concept", "title": "Power dynamics"}, {"id": "4f8d04ab-91df-4260-bfcd-f8ec62d2990f", "type": "concept", "title": "Cognitive bias"}, {"id": "30b5c490-1886-4c69-97bd-f460bd44495e", "type": "concept", "title": "Moral distress"}]}, {"id": "fae4cd2f-9ed5-447b-9904-565f719f89c6", "type": "subtopic", "title": "Negotiation and difficult conversations", "description": "Nurse leaders need practical language for addressing performance, disagreement, and patient-family concerns.", "children": [{"id": "fcf922ad-209d-4479-ac66-926c55333c82", "type": "concept", "title": "Interest-based negotiation"}, {"id": "23b22daf-7748-4368-a4d1-64b4c38c0e8e", "type": "concept", "title": "DESC scripting"}, {"id": "9dbc2ad4-a554-4e40-b3c5-ff11c6538cd9", "type": "concept", "title": "Feedback conversations"}, {"id": "365f26f6-f3ec-410c-a260-c9cef28e99a6", "type": "concept", "title": "Boundary setting"}]}, {"id": "9d5b04ce-c1ba-4fd0-a5ed-3af2cb2c316b", "type": "subtopic", "title": "Psychological safety and civility", "description": "Psychological safety supports speaking up, learning from error, and maintaining respectful teams.", "children": [{"id": "29bc76d8-5e25-4556-acab-e153966ee135", "type": "concept", "title": "Speaking up"}, {"id": "f9b47ffd-98bd-46ca-a3ce-75d4711cef8a", "type": "concept", "title": "Civility"}, {"id": "d56b1b34-0b55-4c95-b153-58465a58d3b9", "type": "concept", "title": "Bullying prevention"}, {"id": "409486cb-8d3b-4da6-a465-9662c6704cd6", "type": "concept", "title": "Repair after conflict"}]}]}, {"id": "3cab409d-1216-4d8a-8a35-ae24c162c834", "type": "topic", "title": "Quality Improvement Methods and Data-Driven Decision-Making", "description": "Use QI methods, measures, and feedback cycles to improve care processes and patient outcomes.", "children": [{"id": "8a26c927-25a2-4851-9a5a-a5560e3b7768", "type": "subtopic", "title": "Model for improvement and PDSA", "description": "QI methods help students test small changes, learn quickly, and avoid confusing effort with improvement.", "children": [{"id": "f56c5822-1ed6-44f3-8d92-1eec0115b71e", "type": "concept", "title": "Aim statements"}, {"id": "62a545ed-0dcf-44b5-acf2-f5c39fa19bd3", "type": "concept", "title": "Driver diagrams"}, {"id": "ba99af30-f643-4a9c-803e-aa3149f0f4c3", "type": "concept", "title": "PDSA cycles"}, {"id": "f6139249-f952-4abf-91cd-aea39f8fd383", "type": "concept", "title": "Rapid-cycle testing"}]}, {"id": "1aef64e6-ffa9-4a22-8a71-e125bf24538c", "type": "subtopic", "title": "Lean, Six Sigma, and process analysis", "description": "Process methods help leaders see waste, variation, delays, and defects in care delivery.", "children": [{"id": "c6ddd8f8-2eeb-49a5-b40f-c84758cc2fb9", "type": "concept", "title": "Process mapping"}, {"id": "bbdd670d-fdd0-4d51-aa6d-0ed9a867afe1", "type": "concept", "title": "Waste reduction"}, {"id": "5fba2754-899a-4fe4-af97-68bf3b17a7cc", "type": "concept", "title": "Root cause patterns"}, {"id": "250a1e87-e98a-4e58-8a0c-fd33b245b861", "type": "concept", "title": "Standard work"}]}, {"id": "887d591b-3628-4d2b-a083-5c396ff2eb1a", "type": "subtopic", "title": "Measurement for improvement", "description": "Students learn to choose measures that reveal whether change is helping, harming, or merely moving work around.", "children": [{"id": "58bea1f7-9769-4b2e-a584-035d293e41d5", "type": "concept", "title": "Outcome measures"}, {"id": "6138c9be-3b21-4bb3-b076-f2937f68b9b0", "type": "concept", "title": "Process measures"}, {"id": "f528600e-6861-4d57-afca-ac557aa985af", "type": "concept", "title": "Balancing measures"}, {"id": "05bda419-c3d4-4e86-82ec-fc97bc66cd92", "type": "concept", "title": "Run charts and control charts"}]}]}, {"id": "68474a19-0953-46e2-9f5d-8d1573ea7d9c", "type": "topic", "title": "Patient Safety, High Reliability, Human Factors, and Just Culture", "description": "Analyze harm as a systems problem and design safer care through reliability principles, human factors, and fair accountability.", "children": [{"id": "791a9dd1-b6de-45fe-90dd-86faf610448b", "type": "subtopic", "title": "Patient safety science", "description": "Safety science reframes harm as the result of interacting system conditions, not simply individual failure.", "children": [{"id": "54751ce2-fd30-4e27-a9cd-25e8ac16bcb7", "type": "concept", "title": "Swiss cheese model"}, {"id": "c3de1437-71d7-4dd9-b161-d5dd32e174b6", "type": "concept", "title": "Latent conditions"}, {"id": "66b5b52e-0d9c-40e6-a60e-f4ad7be6b5a0", "type": "concept", "title": "Near misses"}, {"id": "01d14b21-b88b-40e6-8961-632259613006", "type": "concept", "title": "Safety reporting"}]}, {"id": "3484ee9b-f31c-45e4-8b24-2cd9c7459d01", "type": "subtopic", "title": "High reliability and just culture", "description": "High reliability organizations anticipate failure, learn from weak signals, and hold people fairly accountable.", "children": [{"id": "f684a4b0-6499-40c5-85e3-866b2a2d0536", "type": "concept", "title": "Preoccupation with failure"}, {"id": "e32ddeb9-b8d2-41d6-b768-15aedec44aa4", "type": "concept", "title": "Reluctance to simplify"}, {"id": "7a70c964-184e-4b31-99eb-e78b5e6fe475", "type": "concept", "title": "Sensitivity to operations"}, {"id": "9e7fab5d-1a8e-4518-9632-b566f648d611", "type": "concept", "title": "Just culture algorithms"}]}, {"id": "8775565c-aa4c-433d-9345-40e11bea6c4d", "type": "subtopic", "title": "Human factors and error prevention", "description": "Human factors helps students design work that fits human limits and reduces predictable mistakes.", "children": [{"id": "f2b37af0-f4a4-4d6f-89fe-ec4853997d6f", "type": "concept", "title": "Cognitive load"}, {"id": "fd811a72-c541-4e7b-bed3-46eac66b3474", "type": "concept", "title": "Forcing functions"}, {"id": "38005314-00f6-439d-bdb5-640aed3c49fd", "type": "concept", "title": "Checklists"}, {"id": "dbd87d9c-1b1b-4197-be71-6d1243f99360", "type": "concept", "title": "Medication safety and fall prevention"}]}]}, {"id": "2f2d9b41-fa6f-4389-8ec2-ce59de4819b3", "type": "topic", "title": "Budgeting, Resource Management, and Value-Based Care", "description": "Connect clinical leadership to finance, productivity, resource stewardship, access, and value without losing sight of patient care.", "children": [{"id": "ef69cbd1-dd1b-453b-a387-85aa5f53a439", "type": "subtopic", "title": "Budgeting and finance basics", "description": "Financial literacy allows nurse leaders to advocate credibly for staffing, supplies, technology, and quality investments.", "children": [{"id": "42b416bd-e0b6-476e-8aad-83681c2a6828", "type": "concept", "title": "Operating budgets"}, {"id": "b64d0c3c-a6ac-4adc-923a-3eb3f5aa9b91", "type": "concept", "title": "Capital budgets"}, {"id": "cccf233a-8a5e-40bc-ad56-f47e266d3b17", "type": "concept", "title": "Cost centers"}, {"id": "4fbb2931-0b31-459e-8057-31a65997cc1c", "type": "concept", "title": "Variance analysis"}]}, {"id": "f21f6b82-df8d-4876-adda-c02e32d4aeb6", "type": "subtopic", "title": "Resource stewardship", "description": "Resource management is framed as an ethical balance among patient need, workforce limits, waste reduction, and access.", "children": [{"id": "a6ca9f23-5997-48d6-ae08-45699dde0657", "type": "concept", "title": "Productivity"}, {"id": "c0adca0d-edd9-4850-9e59-2a6fc9099f95", "type": "concept", "title": "Supply use"}, {"id": "bfb0a5be-72d1-4929-bbfb-af17e2e4d14f", "type": "concept", "title": "Capacity planning"}, {"id": "a4ec9d5f-840d-4438-b080-e3bdf636a996", "type": "concept", "title": "Waste and overuse"}]}, {"id": "00e2ba7d-1750-413a-b0d7-1ff29e982f41", "type": "subtopic", "title": "Value and outcomes", "description": "Value-based care connects quality, safety, experience, equity, and cost into leadership decision-making.", "children": [{"id": "0812766a-db25-4e00-9912-aa6f695e5611", "type": "concept", "title": "Quality metrics"}, {"id": "4c9a3492-49b9-4f47-82e7-8a921799f69a", "type": "concept", "title": "Patient experience"}, {"id": "078e6614-90cb-4bda-adf8-d2e9b704dbcb", "type": "concept", "title": "Readmissions"}, {"id": "06a82b90-1a39-41f7-8cc0-861c69773f46", "type": "concept", "title": "Cost of poor quality"}]}]}, {"id": "66fe9a10-1432-47d0-97d5-022a0d3129b3", "type": "topic", "title": "Healthcare Policy, Regulation, Advocacy, Ethics, and Risk Management", "description": "Link bedside leadership to law, policy, advocacy, ethical reasoning, compliance, and organizational risk reduction.", "children": [{"id": "c309ea92-0002-46ee-8fb4-7b82875a9195", "type": "subtopic", "title": "Policy and advocacy", "description": "Students learn how nurse leaders influence policy inside organizations and in the broader healthcare environment.", "children": [{"id": "4096e817-f110-43b1-aada-b2dbe6085728", "type": "concept", "title": "Legislative advocacy"}, {"id": "ec1ec611-20e6-449b-9779-bc7bab3fd32b", "type": "concept", "title": "Professional organizations"}, {"id": "ca035fb4-595f-436d-a572-74ed54ec36d2", "type": "concept", "title": "Scope-of-practice policy"}, {"id": "318ad2db-98cf-4f6e-bc8e-3f7a2ff6ff6f", "type": "concept", "title": "Workplace policy"}]}, {"id": "a6d38092-0cda-4599-89d1-a409d6193043", "type": "subtopic", "title": "Regulation, accreditation, and compliance", "description": "Regulatory literacy helps leaders translate external requirements into safe and realistic practice.", "children": [{"id": "be2c16bf-fb1c-466d-9cf6-3d266e647b2e", "type": "concept", "title": "State boards of nursing"}, {"id": "1fbec55a-e62d-4569-b97a-513cf105f73e", "type": "concept", "title": "Accreditation"}, {"id": "2fd86d57-07f8-441b-9d11-dc605b2a4ec7", "type": "concept", "title": "CMS requirements"}, {"id": "5cdbc485-e54b-4f7f-8fe3-93b536aee75a", "type": "concept", "title": "Privacy and documentation"}]}, {"id": "a2c07e1d-dc5e-4b65-a442-7d9f9208af99", "type": "subtopic", "title": "Ethics, legal issues, and risk management", "description": "Risk management connects ethical reasoning, legal duty, documentation, and prevention of avoidable harm.", "children": [{"id": "882a548a-8152-4b1e-9f5b-177f919e8111", "type": "concept", "title": "Informed consent"}, {"id": "203324b6-bb33-428f-b873-6870fb06b123", "type": "concept", "title": "Negligence and malpractice"}, {"id": "f0ee5f2e-6b30-4dbf-9a30-c72429d74112", "type": "concept", "title": "Incident reporting"}, {"id": "f70136b9-0005-4dea-b38e-bfe44a986d2d", "type": "concept", "title": "Risk mitigation plans"}]}]}, {"id": "d1629d03-ce8c-416a-90f6-218be1ec1345", "type": "topic", "title": "Change Management, Innovation, and Implementation Science", "description": "Move from good ideas to sustained practice change using change theory, stakeholder engagement, and implementation strategies.", "children": [{"id": "404644af-4578-43a8-81e9-5dea5249ea4e", "type": "subtopic", "title": "Change theory", "description": "Change theory gives students a way to understand resistance, readiness, momentum, and sustainability.", "children": [{"id": "df6025d6-bbff-405d-bd7c-50eb32f293a1", "type": "concept", "title": "Lewin"}, {"id": "534bbfa2-47b3-4daa-8e99-8b584c530fe7", "type": "concept", "title": "Kotter"}, {"id": "66d9b4c3-f4dd-4497-b049-aaa0bb6e1712", "type": "concept", "title": "ADKAR"}, {"id": "5242fd9e-533f-4775-a8ff-e41f6a17e1a8", "type": "concept", "title": "Readiness assessment"}]}, {"id": "f91c6707-6d49-4338-b8b4-21aa6352efd1", "type": "subtopic", "title": "Implementation strategies", "description": "Implementation science helps convert evidence into practice in real clinical environments.", "children": [{"id": "ab194258-fd97-462c-835e-5ca7982dea75", "type": "concept", "title": "Stakeholder analysis"}, {"id": "5764f3e6-33c7-4464-b25f-0328d3d585e1", "type": "concept", "title": "Champions"}, {"id": "b7de0f8d-955f-40f4-a4e3-a9aa8f897dc9", "type": "concept", "title": "Audit and feedback"}, {"id": "c49853a5-eea9-46e9-8166-865df991edab", "type": "concept", "title": "Sustainment planning"}]}, {"id": "7c26b0a4-1fee-4948-b795-d4e99a318403", "type": "subtopic", "title": "Innovation and digital transformation", "description": "Nurse leaders increasingly guide technology adoption, workflow redesign, and ethical innovation.", "children": [{"id": "0a51fc15-414d-4390-a9ee-f991cb0ae912", "type": "concept", "title": "EHR workflow"}, {"id": "01c48160-b485-4e40-8714-224d11596c1d", "type": "concept", "title": "Clinical decision support"}, {"id": "0c0c0c21-e6db-4d09-be66-57e3e088aa05", "type": "concept", "title": "Telehealth"}, {"id": "1ff2663c-367c-40f8-ae5e-51ca732df756", "type": "concept", "title": "Change fatigue"}]}]}, {"id": "dc7de9d7-2242-47ad-ace2-2296cee0a9c0", "type": "topic", "title": "Equity, Inclusive Leadership, and Culture of Belonging", "description": "Prepare nurse leaders to recognize inequity, lead across difference, and build teams where patients and staff can thrive.", "children": [{"id": "66bff453-b078-4329-94f6-32949a8be341", "type": "subtopic", "title": "Equity-centered leadership", "description": "Equity-centered leadership asks students to notice who benefits, who is burdened, and whose voice is missing.", "children": [{"id": "a499ffc4-93a4-4296-b94e-05204aac47a1", "type": "concept", "title": "Health disparities"}, {"id": "04b97563-332e-43c9-8935-9a0e1f8860ef", "type": "concept", "title": "Structural racism"}, {"id": "52a32db5-f945-49b7-9898-4f81f34669d5", "type": "concept", "title": "Language access"}, {"id": "b37681eb-8fc0-4ce0-8d7a-bf464f680f8b", "type": "concept", "title": "Equity dashboards"}]}, {"id": "92c5daa5-7179-4ba5-bb44-972c99c58017", "type": "subtopic", "title": "Inclusive team leadership", "description": "Inclusive leaders build participation, belonging, and fair opportunity across diverse teams.", "children": [{"id": "c96c7a71-c971-4c5b-be96-64e001156ae5", "type": "concept", "title": "Bias awareness"}, {"id": "c16c93d8-1093-442b-99b4-fb19530ab910", "type": "concept", "title": "Inclusive meetings"}, {"id": "c227828f-e7bb-4bc5-9005-1ae108821d5f", "type": "concept", "title": "Cultural humility"}, {"id": "f5232c88-22bf-4ad0-9fd3-7d8267ce8395", "type": "concept", "title": "Mentorship and sponsorship"}]}, {"id": "5260e710-623f-4143-9e1e-551b4f024002", "type": "subtopic", "title": "Patient and community partnership", "description": "Leadership becomes stronger when patients, families, and communities help define quality and safety.", "children": [{"id": "6cb72571-8bd2-4179-addc-7415351b890b", "type": "concept", "title": "Patient advisory councils"}, {"id": "2c9ea4bf-d36d-4f8b-a52e-3d4e4bdf3123", "type": "concept", "title": "Community engagement"}, {"id": "e9fce25d-cdb5-4c85-b2bc-ee4c9f4459ab", "type": "concept", "title": "Trauma-informed communication"}, {"id": "2e683e22-22ce-436f-b832-8265800663f1", "type": "concept", "title": "Trust-building"}]}]}, {"id": "05729c9d-164f-482a-98a3-bd987573bda6", "type": "topic", "title": "Transition to Practice, Career Development, and Reflective Leadership Portfolio", "description": "Integrate course learning into a personal leadership stance, professional development plan, and evidence-based capstone artifact.", "children": [{"id": "3196a951-ae2d-4a9a-83ba-9723290f74d6", "type": "subtopic", "title": "Transition to professional practice", "description": "Students prepare for the shift from supervised student role to accountable professional nurse.", "children": [{"id": "5deb04a1-f720-4e75-8065-6ef788fd750e", "type": "concept", "title": "Reality shock"}, {"id": "4b2e6be6-db21-4a45-bd79-4d834b910042", "type": "concept", "title": "Residency programs"}, {"id": "0a676aae-2d11-466a-a56d-5be56b4da591", "type": "concept", "title": "Prioritization"}, {"id": "ee2e2c63-8a64-46d5-8765-a813e81d9529", "type": "concept", "title": "Professional communication"}]}, {"id": "1075cf06-d0cd-4e53-aaac-e4f6b97f1449", "type": "subtopic", "title": "Career development and lifelong learning", "description": "Career planning helps students connect leadership growth to certification, graduate study, specialty practice, and service.", "children": [{"id": "d691dd1b-e916-42a9-abef-826152a25440", "type": "concept", "title": "Mentoring"}, {"id": "5eb28420-cc7a-43d8-b064-fb60c278ae58", "type": "concept", "title": "Professional goals"}, {"id": "3995a8eb-b867-4914-aa2c-281520d715d8", "type": "concept", "title": "Certification pathways"}, {"id": "3f79511e-d99b-41b3-a89a-29ceb9883dbd", "type": "concept", "title": "Continuing competence"}]}, {"id": "2a9e8009-27d8-43c5-82f4-3232e1b4057a", "type": "subtopic", "title": "Reflective leadership portfolio", "description": "The portfolio turns the course into evidence of growth, readiness, and practical leadership judgment.", "children": [{"id": "5268b643-8a06-4276-b3cb-ee5ae48e7c8d", "type": "concept", "title": "Leadership philosophy"}, {"id": "65f8f9c9-2504-41e3-97e1-914a73628438", "type": "concept", "title": "QI proposal"}, {"id": "f5666559-6f05-4365-9649-14c431bcc206", "type": "concept", "title": "Delegation case reflection"}, {"id": "2a0a9da5-dcd9-4b64-9e35-509f58ee812a", "type": "concept", "title": "Professional development plan"}]}]}], "dbBacked": true}$nlmjson$::jsonb,
